"use client";

import React, { useState } from 'react';
import {
    Calendar as CalendarIcon,
    Clock,
    User,
    Scissors,
    ChevronLeft,
    ChevronRight,
    MoreHorizontal,
    CheckCircle2,
    Play,
    Pause,
    XCircle,
    Phone,
    MessageSquare,
    History,
    FileText,
    Settings,
    Coffee
} from 'lucide-react';
import { Button } from '@/components/ui/Button';

// Mock Data
const appointments = [
    { id: 1, time: '09:00', client: 'João Silva', service: 'Corte Degradê', status: 'CONCLUÍDO', phone: '+55 11 99999-1111' },
    { id: 2, time: '09:40', client: 'Pedro Santos', service: 'Barba Completa', status: 'EM ATENDIMENTO', phone: '+55 11 99999-2222' },
    { id: 3, time: '10:30', client: 'Carlos Oliveira', service: 'Combo Premium', status: 'AGENDADO', phone: '+55 11 99999-3333' },
    { id: 4, time: '11:15', client: 'Roberto Souza', service: 'Corte Social', status: 'AGENDADO', phone: '+55 11 99999-4444' },
    { id: 5, time: '12:00', client: 'INTERVALO', service: 'Almoço', status: 'BLOQUEADO' },
    { id: 6, time: '14:00', client: 'Marcos Vinicius', service: 'Degradê + Pigmentação', status: 'AGENDADO', phone: '+55 11 99999-5555' },
    { id: 7, time: '15:00', client: 'Felipe Amorim', service: 'Barba Terapêutica', status: 'AGENDADO', phone: '+55 11 99999-6666' },
];

export default function BarberSchedule() {
    const [selectedDate, setSelectedDate] = useState(new Date());
    const [activeApt, setActiveApt] = useState<any>(null);

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'CONCLUÍDO': return 'text-emerald-400 bg-emerald-400/10 border-emerald-400/20';
            case 'EM ATENDIMENTO': return 'text-amber-400 bg-amber-400/10 border-amber-400/20';
            case 'AGENDADO': return 'text-[var(--color-primary-gold)] bg-[var(--color-primary-gold)]/10 border-[var(--color-primary-gold)]/20';
            case 'CANCELADO': return 'text-red-400 bg-red-400/10 border-red-400/20';
            case 'BLOQUEADO': return 'text-gray-500 bg-white/5 border-white/10';
            default: return 'text-gray-400 bg-white/5 border-white/5';
        }
    };

    return (
        <div className="max-w-6xl mx-auto space-y-10 animate-fade-in-up">
            <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-white/5">
                <div className="flex items-center gap-6">
                    <div className="w-16 h-16 bg-[var(--color-primary-gold)]/10 border border-[var(--color-primary-gold)]/30 rounded-3xl flex flex-col items-center justify-center text-[var(--color-primary-gold)] shadow-inner">
                        <p className="text-[10px] font-black uppercase tracking-widest leading-none mb-1">MAR</p>
                        <p className="text-xl font-black leading-none">09</p>
                    </div>
                    <div>
                        <h1 className="text-3xl font-bold tracking-tight mb-1">Minha <span className="text-[var(--color-primary-gold)]">Agenda</span></h1>
                        <p className="text-gray-500 text-sm italic">Hoje, Segunda-feira</p>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    <Button variant="outline" className="h-12 px-5 rounded-2xl border-white/5 bg-black/40 text-[10px] font-black uppercase tracking-[0.2em] gap-2">
                        <Coffee className="w-4 h-4" /> BLOQUEAR HORÁRIO
                    </Button>
                    <div className="flex bg-black/40 p-1 rounded-2xl border border-white/5">
                        <button className="p-3 text-gray-400 hover:text-white transition-colors"><ChevronLeft size={20} /></button>
                        <button className="px-6 py-2 text-[10px] font-black uppercase tracking-widest text-white">MARÇO, 2026</button>
                        <button className="p-3 text-gray-400 hover:text-white transition-colors"><ChevronRight size={20} /></button>
                    </div>
                </div>
            </header>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
                {/* Daily Schedule List */}
                <div className="lg:col-span-2 space-y-4">
                    {appointments.map((apt) => (
                        <div
                            key={apt.id}
                            onClick={() => apt.status !== 'BLOQUEADO' && setActiveApt(apt)}
                            className={`group relative overflow-hidden bg-[var(--color-dark-card)] border-2 transition-all duration-300 p-6 rounded-[2.5rem] flex items-center justify-between cursor-pointer ${activeApt?.id === apt.id
                                    ? 'border-[var(--color-primary-gold)] shadow-[0_10px_30px_rgba(212,175,55,0.1)]'
                                    : 'border-white/5 border-dashed hover:border-white/20'
                                }`}
                        >
                            <div className="flex items-center gap-8">
                                <div className="text-center min-w-[60px]">
                                    <p className="text-xl font-black text-white leading-none">{apt.time}</p>
                                    <div className="w-8 h-0.5 bg-[var(--color-primary-gold)] mx-auto mt-2 opacity-50" />
                                </div>

                                <div className="space-y-1">
                                    <div className="flex items-center gap-3">
                                        <h4 className={`text-lg font-bold tracking-tight transition-colors ${apt.status === 'BLOQUEADO' ? 'text-gray-600 italic' : 'text-white'}`}>
                                            {apt.client}
                                        </h4>
                                        <span className={`px-2 py-0.5 rounded-lg border text-[8px] font-black uppercase tracking-widest ${getStatusColor(apt.status)}`}>
                                            {apt.status}
                                        </span>
                                    </div>
                                    <p className={`text-xs font-medium italic ${apt.status === 'BLOQUEADO' ? 'text-gray-700' : 'text-gray-500'}`}>
                                        {apt.service}
                                    </p>
                                </div>
                            </div>

                            <div className="flex items-center gap-2 scale-0 group-hover:scale-100 transition-all origin-right">
                                {apt.status === 'AGENDADO' && (
                                    <Button size="sm" className="h-10 w-10 p-0 rounded-xl bg-emerald-500 hover:bg-emerald-600 text-black shadow-lg shadow-emerald-500/10">
                                        <Play className="w-4 h-4 fill-current" />
                                    </Button>
                                )}
                                {apt.status === 'EM ATENDIMENTO' && (
                                    <Button size="sm" className="h-10 w-10 p-0 rounded-xl bg-blue-500 hover:bg-blue-600 text-black shadow-lg shadow-blue-500/10">
                                        <CheckCircle2 className="w-4 h-4" />
                                    </Button>
                                )}
                                <Button variant="outline" size="sm" className="h-10 w-10 p-0 rounded-xl border-white/10 text-gray-400 hover:text-white hover:border-white/30">
                                    <MoreHorizontal className="w-4 h-4" />
                                </Button>
                            </div>
                        </div>
                    ))}
                </div>

                {/* Right Panel: Client Details / Quick Actions */}
                <div className="space-y-8">
                    {activeApt ? (
                        <div className="bg-[var(--color-dark-card)] border border-[var(--color-dark-border)] rounded-[3rem] p-10 shadow-2xl space-y-8 sticky top-32 animate-fade-in-up">
                            <div className="text-center space-y-4">
                                <div className="w-24 h-24 rounded-3xl border-2 border-[var(--color-primary-gold)]/30 p-1 mx-auto relative group">
                                    <div className="absolute inset-0 bg-[var(--color-primary-gold)]/5 rounded-3xl blur-xl group-hover:bg-[var(--color-primary-gold)]/20 transition-all" />
                                    <div className="w-full h-full bg-black rounded-2xl flex items-center justify-center text-[var(--color-primary-gold)] relative z-10 overflow-hidden">
                                        <User size={48} strokeWidth={1} />
                                    </div>
                                    <div className="absolute -bottom-2 -right-2 bg-emerald-500 w-6 h-6 rounded-lg border-4 border-[var(--color-dark-card)]" title="Fiel há 1 ano" />
                                </div>
                                <div>
                                    <h3 className="text-2xl font-black text-white tracking-tight">{activeApt.client}</h3>
                                    <p className="text-[10px] text-gray-500 font-bold uppercase tracking-[0.2em] mt-1 italic">Cliente Frequente</p>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <Button variant="outline" className="h-14 rounded-2xl border-white/5 bg-black/40 text-[10px] font-black uppercase tracking-widest gap-2">
                                    <Phone className="w-4 h-4 text-emerald-400" /> LIGAR
                                </Button>
                                <Button variant="outline" className="h-14 rounded-2xl border-white/5 bg-black/40 text-[10px] font-black uppercase tracking-widest gap-2">
                                    <MessageSquare className="w-4 h-4 text-blue-400" /> WHATSAPP
                                </Button>
                            </div>

                            <div className="space-y-6 pt-6 border-t border-white/5">
                                <h4 className="text-sm font-bold flex items-center gap-2 italic">
                                    <History className="w-4 h-4 text-[var(--color-primary-gold)]" /> Histórico Rápido
                                </h4>
                                <div className="space-y-4">
                                    {[
                                        { date: '15 Fev', service: 'Corte Degradê', price: 'R$ 55' },
                                        { date: '28 Jan', service: 'Corte + Barba', price: 'R$ 85' },
                                    ].map((h, i) => (
                                        <div key={i} className="flex items-center justify-between text-xs p-3 bg-black/40 rounded-xl border border-white/5">
                                            <span className="text-gray-500 font-bold">{h.date}</span>
                                            <span className="text-white font-medium">{h.service}</span>
                                            <span className="text-[var(--color-primary-gold)] font-black">{h.price}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            <div className="space-y-4 pt-6">
                                <Button className="w-full h-16 rounded-2xl bg-emerald-600 hover:bg-emerald-700 text-black font-black uppercase text-[11px] tracking-[0.2em] shadow-xl shadow-emerald-500/10">
                                    INICIAR ATENDIMENTO
                                </Button>
                                <Button variant="outline" className="w-full h-14 rounded-2xl border-red-500/20 text-red-500 hover:bg-red-500/10 font-black uppercase text-[10px] tracking-widest border-dashed">
                                    CANCELAR HORÁRIO
                                </Button>
                            </div>
                        </div>
                    ) : (
                        <div className="bg-[var(--color-dark-card)] border border-[var(--color-dark-border)] border-dashed rounded-[3rem] p-16 text-center space-y-6">
                            <div className="w-20 h-20 bg-white/5 rounded-full flex items-center justify-center mx-auto text-gray-700">
                                <Scissors size={32} />
                            </div>
                            <div>
                                <h3 className="text-lg font-bold text-gray-500">Nenhum cliente selecionado</h3>
                                <p className="text-xs text-gray-600 mt-2 italic px-8">Clique em um agendamento na lista ao lado para ver detalhes e gerenciar o atendimento.</p>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}
